UPDATE TBL_CLOSING_MST SET ACTION_YN='N', UPD_DTTM=CONVERT(VARCHAR(19),GETDATE(),120), UPD_USER=#{updUser,jdbcType=NVARCHAR}, UPD_IP=#{updIp,jdbcType=NVARCHAR}
 WHERE CLOSE_YM = #{closeYm}
   AND ( ISNULL(#{compCd,jdbcType=VARCHAR},'') = '' OR COMP_CD = #{compCd,jdbcType=VARCHAR} )

UPDATE TBL_PROD_INPRICE_HST
   SET ACTION_YN='N', UPD_DTTM=CONVERT(VARCHAR(19), GETDATE(), 120), UPD_USER=#{updUser,jdbcType=NVARCHAR}, UPD_IP=#{updIp,jdbcType=NVARCHAR}
 WHERE INPRICE_SEQ = #{inpriceSeq}
   AND ( ISNULL(#{compCd,jdbcType=VARCHAR},'') = '' OR COMP_CD = #{compCd,jdbcType=VARCHAR} )

UPDATE TBL_PROD_MST
   SET IN_PRICE = #{inPrice,jdbcType=DECIMAL},
       UPD_DTTM = CONVERT(VARCHAR(19), GETDATE(), 120), UPD_USER=#{regUser,jdbcType=NVARCHAR}, UPD_IP=#{regIp,jdbcType=NVARCHAR}
 WHERE PROD_SEQ = #{prodSeq}
   AND ( ISNULL(#{compCd,jdbcType=VARCHAR},'') = '' OR COMP_CD = #{compCd,jdbcType=VARCHAR} )

UPDATE TBL_PROD_SALEPRICE_HST
   SET ACTION_YN='N', UPD_DTTM=CONVERT(VARCHAR(19), GETDATE(), 120), UPD_USER=#{updUser,jdbcType=NVARCHAR}, UPD_IP=#{updIp,jdbcType=NVARCHAR}
 WHERE SALEPRICE_SEQ = #{salepriceSeq}
   AND ( ISNULL(#{compCd,jdbcType=VARCHAR},'') = '' OR COMP_CD = #{compCd,jdbcType=VARCHAR} )

UPDATE TBL_PROD_MST
   SET SALE_PRICE  = #{salePrice,jdbcType=DECIMAL},
       WHOLE_PRICE = ISNULL(#{wholePrice,jdbcType=DECIMAL}, WHOLE_PRICE),
       UPD_DTTM = CONVERT(VARCHAR(19), GETDATE(), 120), UPD_USER=#{regUser,jdbcType=NVARCHAR}, UPD_IP=#{regIp,jdbcType=NVARCHAR}
 WHERE PROD_SEQ = #{prodSeq}
   AND ( ISNULL(#{compCd,jdbcType=VARCHAR},'') = '' OR COMP_CD = #{compCd,jdbcType=VARCHAR} )

UPDATE TBL_STOCK_LEDGER
   SET ACTION_YN='N', UPD_DTTM=CONVERT(VARCHAR(19), GETDATE(), 120), UPD_USER=#{updUser,jdbcType=NVARCHAR}, UPD_IP=#{updIp,jdbcType=NVARCHAR}
 WHERE LEDGER_SEQ = #{ledgerSeq}
   AND ISNULL(REF_GB,'') = ''
   AND ( ISNULL(#{compCd,jdbcType=VARCHAR},'') = '' OR COMP_CD = #{compCd,jdbcType=VARCHAR} )

mapper.insert:
INSERT INTO TBL_STOCK_LEDGER (COMP_CD, PROD_SEQ, PROD_CD, TRX_DT, IO_GB, QTY, UNIT_PRICE, AMT, BIZ_CD, REF_GB, REF_NO, REMARK, ACTION_YN, REG_DTTM, REG_USER, REG_IP) SELECT COMP_CD, PROD_SEQ, PROD_CD, DLV_DT, IO_GB, QTY, NULL, NULL, NULL, 'SALES', DLV_DT, REMARK, 'Y', CONVERT(VARCHAR(19),GETDATE(),120), #{regUser,jdbcType=NVARCHAR}, #{regIp,jdbcType=NVARCHAR} FROM ( /* ── 출고행 : 정상은 정산수량, 반품행은 '나갔던' 발주량 ── */ SELECT s.COMP_CD, s.PROD_SEQ, MAX(s.PROD_CD) AS PROD_CD, s.DLV_DT, 'O' AS IO_GB, SUM( CASE WHEN ISNULL(s.DLV_TYPE,'') = 'X' THEN ISNULL(s.ORD_QTY,0) ELSE ISNULL(s.OUT_QTY,0) END ) AS QTY, N'출고 자동연동(정산서)' AS REMARK FROM TBL_SALES_MST s WHERE s.ACTION_YN = 'Y' AND s.PROD_SEQ IS NOT NULL AND ( ISNULL(#{compCd,jdbcType=VARCHAR},'') = '' OR s.COMP_CD = #{compCd,jdbcType=VARCHAR} ) AND s.DLV_DT = REPLACE(ISNULL(#{trxDt},''),'-','') GROUP BY s.COMP_CD, s.PROD_SEQ, s.DLV_DT
UNION ALL
/* ── 반품행 : 되돌려 받은 수량. 잔량이 소수로 남는 건(R4)은 잡지 않는다 ── */ SELECT s.COMP_CD, s.PROD_SEQ, MAX(s.PROD_CD) AS PROD_CD, s.DLV_DT, 'R' AS IO_GB, SUM( CASE WHEN ISNULL(s.DLV_TYPE,'') = 'X' AND ( ISNULL(s.ORD_QTY,0) + ISNULL(s.OUT_QTY,0) = 0 /* R2 */ OR ( ISNULL(s.ORD_QTY,0) + ISNULL(s.OUT_QTY,0) > 0 /* R3 */ AND ISNULL(s.ORD_QTY,0) + ISNULL(s.OUT_QTY,0) = FLOOR(ISNULL(s.ORD_QTY,0) + ISNULL(s.OUT_QTY,0)) ) ) THEN ABS(ISNULL(s.OUT_QTY,0)) ELSE 0 END ) AS QTY, N'반품 자동연동(정산서)' AS REMARK FROM TBL_SALES_MST s WHERE s.ACTION_YN = 'Y' AND s.PROD_SEQ IS NOT NULL AND ISNULL(s.DLV_TYPE,'') = 'X' AND ( ISNULL(#{compCd,jdbcType=VARCHAR},'') = '' OR s.COMP_CD = #{compCd,jdbcType=VARCHAR} ) AND s.DLV_DT = REPLACE(ISNULL(#{trxDt},''),'-','') GROUP BY s.COMP_CD, s.PROD_SEQ, s.DLV_DT ) d WHERE d.QTY > 0

