UPDATE TBL_STOCK_ADJ_HIS
   SET ACTION_YN='N', UPD_DTTM=CONVERT(VARCHAR(19),GETDATE(),120),
       UPD_USER=#{regUser,jdbcType=NVARCHAR}, UPD_IP=#{regIp,jdbcType=NVARCHAR}
 WHERE BATCH_NO = #{batchNo,jdbcType=NVARCHAR}
   AND ACTION_YN = 'Y'
   AND ( ISNULL(#{compCd,jdbcType=VARCHAR},'') = '' OR COMP_CD = #{compCd,jdbcType=VARCHAR} )
